	"oras.land/oras-go/v2/content/oci"
	"oras.land/oras-go/v2/registry"
	"oras.land/oras-go/v2/registry/remote"
)

// Store is a type which can retrieve Flipt feature files from a target repository and reference
// Repositories can be local (OCI layout directories on the filesystem) or a remote registry
type Store struct {
	reference registry.Reference
	store     oras.ReadOnlyTarget
	localPath string
}

// NewStore constructs and configures an instance of *Store for the provided config
func NewStore(conf *config.OCI) (*Store, error) {
	scheme, repository, match := strings.Cut(conf.Repository, "://")

	// support empty scheme as remote and https
	if !match {
		repository = scheme
		scheme = "https"
	}

	ref, err := registry.ParseReference(repository)
	if err != nil {
		return nil, err
	}

	store := &Store{
		reference: ref,
	}
	switch scheme {
	case "http", "https":
		remote, err := remote.NewRepository(fmt.Sprintf("%s/%s", ref.Registry, ref.Repository))
		if err != nil {
			return nil, err
		}

		remote.PlainHTTP = scheme == "http"

		store.store = remote
	case "flipt":
		if ref.Registry != "local" {
			return nil, fmt.Errorf("unexpected local reference: %q", conf.Repository)
		}

		// OCI layout stores cache their index in memory. Open the directory at
		// fetch time so changes made by another process are visible.
		store.localPath = path.Join(conf.BundleDirectory, ref.Repository)
	default:
		return nil, fmt.Errorf("unexpected repository scheme: %q should be one of [http|https|flipt]", scheme)
	}

	return store, nil
}

// FetchOptions configures a call to Fetch
type FetchOptions struct {
	IfNoMatch digest.Digest
}

// FetchResponse contains any fetched files for the given tracked reference
// If Matched == true, then the supplied IfNoMatch digest matched and Files should be nil
type FetchResponse struct {
	Digest  digest.Digest
	Files   []fs.File
	Matched bool
}

// IfNoMatch configures the call to Fetch to return early if the supplied
// digest matches the target manifest pointed at by the underlying reference
// This is a cache optimization to skip re-fetching resources if the contents
// has already been seen by the caller
func IfNoMatch(digest digest.Digest) containers.Option[FetchOptions] {
	return func(fo *FetchOptions) {
		fo.IfNoMatch = digest
	}
}

// Fetch retrieves the associated files for the tracked repository and reference
// It can optionally be configured to skip fetching given the caller has a digest
// that matches the current reference target
func (s *Store) Fetch(ctx context.Context, opts ...containers.Option[FetchOptions]) (*FetchResponse, error) {
	var options FetchOptions
	containers.ApplyAll(&options, opts...)

	store := s.store
	if s.localPath != "" {
		var err error
		store, err = oci.New(s.localPath)
		if err != nil {
			return nil, err
		}
	}

	// Keep the destination local to this fetch. In particular, an old tag in a
	// previously copied index must not hide a newly published local manifest.
	local := memory.New()

	desc, err := oras.Copy(ctx,
		store,
		s.reference.Reference,
		local,
		s.reference.Reference,
		oras.DefaultCopyOptions)
	if err != nil {
		return nil, err
	}

	bytes, err := content.FetchAll(ctx, local, desc)
	if err != nil {
		return nil, err
	}

	var manifest v1.Manifest
	if err = json.Unmarshal(bytes, &manifest); err != nil {
		return nil, err
	}

	var d digest.Digest
	{
		// shadow manifest so that we can safely
		// strip annotations before calculating
		// the digest
		manifest := manifest
		manifest.Annotations = map[string]string{}
		bytes, err := json.Marshal(&manifest)
		if err != nil {
			return nil, err
		}

		d = digest.FromBytes(bytes)
		if d == options.IfNoMatch {
			return &FetchResponse{Matched: true, Digest: d}, nil
		}
	}

	files, err := s.fetchFiles(ctx, store, manifest)
	if err != nil {
		return nil, err
	}

	return &FetchResponse{Files: files, Digest: d}, nil
}

// fetchFiles retrieves the associated flipt feature content files from the content fetcher.
// It traverses the provided manifests and returns a slice of file instances with appropriate
// content type extensions.
func (s *Store) fetchFiles(ctx context.Context, store oras.ReadOnlyTarget, manifest v1.Manifest) ([]fs.File, error) {
	var files []fs.File

	var created time.Time
	if value := manifest.Annotations[v1.AnnotationCreated]; value != "" {
		var err error
		created, err = time.Parse(time.RFC3339, value)
		if err != nil {
			return nil, fmt.Errorf("manifest creation time: %w", err)
		}
	}

	for _, layer := range manifest.Layers {
		mediaType, encoding, err := getMediaTypeAndEncoding(layer)
		if err != nil {
			return nil, fmt.Errorf("layer %q: %w", layer.Digest, err)
		}

		if mediaType != MediaTypeFliptNamespace && mediaType != MediaTypeFliptFeatures {
			return nil, fmt.Errorf("layer %q: type %q: %w", layer.Digest, mediaType, ErrUnexpectedMediaType)
		}

		format, compressed := encodingFormat(encoding)
		if format == "" {
			return nil, fmt.Errorf("layer %q: unexpected layer encoding: %q", layer.Digest, encoding)
		}

		rc, err := store.Fetch(ctx, layer)
		if err != nil {
			return nil, err
		}
		payload, readErr := io.ReadAll(rc)
		closeErr := rc.Close()
		if readErr != nil {
			return nil, fmt.Errorf("layer %q: %w", layer.Digest, readErr)
		}
		if closeErr != nil {
			return nil, fmt.Errorf("layer %q: %w", layer.Digest, closeErr)
		}

		if compressed {
			reader, err := gzip.NewReader(bytes.NewReader(payload))
			if err != nil {
				return nil, fmt.Errorf("layer %q: gzip: %w", layer.Digest, err)
			}
			payload, err = io.ReadAll(reader)
			closeErr = reader.Close()
			if err != nil {
				return nil, fmt.Errorf("layer %q: gzip: %w", layer.Digest, err)
			}
			if closeErr != nil {
				return nil, fmt.Errorf("layer %q: gzip: %w", layer.Digest, closeErr)
			}
		}

		payload, err = setNamespace(payload, format, layer.Annotations[AnnotationFliptNamespace])
		if err != nil {
			return nil, fmt.Errorf("layer %q: namespace: %w", layer.Digest, err)
		}

		files = append(files, &File{
			ReadCloser: io.NopCloser(bytes.NewReader(payload)),
			info: FileInfo{
				desc:     layer,
				encoding: format,
				size:     int64(len(payload)),
				mod:      created,
			},
		})
	}

	return files, nil
}

// encodingFormat returns a file extension and whether a layer must be
// decompressed before passing its contents to the snapshot parser.
func encodingFormat(encoding string) (string, bool) {
	switch encoding {
	case "", "json":
		return "json", false
	case "yaml", "yml":
		return encoding, false
	case "gzip", "json+gzip":
		return "json", true
	case "yaml+gzip", "yml+gzip":
		return strings.TrimSuffix(encoding, "+gzip"), true
	default:
		return "", false
	}
}

// setNamespace makes the layer annotation authoritative while retaining the
// original bytes when the document already has the expected namespace.
func setNamespace(payload []byte, format, namespace string) ([]byte, error) {
	if namespace == "" {
		return payload, nil
	}

	if format == "json" {
		var doc map[string]json.RawMessage
		if err := json.Unmarshal(payload, &doc); err != nil {
			return nil, err
		}
		if doc == nil {
			return nil, errors.New("expected a JSON object")
		}
		var current string
		if value, ok := doc["namespace"]; ok {
			if err := json.Unmarshal(value, &current); err != nil {
				return nil, err
			}
		}
		if current == namespace {
			return payload, nil
		}
		value, err := json.Marshal(namespace)
		if err != nil {
			return nil, err
		}
		doc["namespace"] = value
		return json.Marshal(doc)
	}

	decoder := yaml.NewDecoder(bytes.NewReader(payload))
	var docs []*yaml.Node
	changed := false
	for {
		var doc yaml.Node
		if err := decoder.Decode(&doc); err != nil {
			if errors.Is(err, io.EOF) {
				break
			}
			return nil, err
		}
		if len(doc.Content) != 1 || doc.Content[0].Kind != yaml.MappingNode {
			return nil, errors.New("expected a YAML mapping")
		}
