		// fetch time so changes made by another process are visible.
		store.localPath = path.Join(conf.BundleDirectory, ref.Repository)
	default:
		return nil, fmt.Errorf("unexpected repository scheme: %q should be one of [http|https|flipt]", scheme)
	}

