	// Fetch the manifest before its layers so IfNoMatch avoids downloading
	// content already represented by the current snapshot.
	desc, err := store.Resolve(ctx, s.reference.Reference)
	if err != nil {
		return nil, err
	}

	bytes, err := content.FetchAll(ctx, store, desc)
	if err != nil {
		return nil, err
	}

	var manifest v1.Manifest
	if err = json.Unmarshal(bytes, &manifest); err != nil {
		return nil, err
	}

	var d digest.Digest
	{
		// shadow manifest so that we can safely
		// strip annotations before calculating
		// the digest
		manifest := manifest
		manifest.Annotations = map[string]string{}
