	var files []fs.File

	var created time.Time
	if value := manifest.Annotations[v1.AnnotationCreated]; value != "" {
		var err error
		created, err = time.Parse(time.RFC3339, value)
		if err != nil {
			return nil, fmt.Errorf("manifest creation time: %w", err)
		}
	}

	for _, layer := range manifest.Layers {
		mediaType, encoding, err := getMediaTypeAndEncoding(layer)
		if err != nil {
			return nil, fmt.Errorf("layer %q: %w", layer.Digest, err)
		}

		if mediaType != MediaTypeFliptNamespace && mediaType != MediaTypeFliptFeatures {
			return nil, fmt.Errorf("layer %q: type %q: %w", layer.Digest, mediaType, ErrUnexpectedMediaType)
		}

		format, compressed := encodingFormat(encoding)
		if format == "" {
			return nil, fmt.Errorf("layer %q: unexpected layer encoding: %q", layer.Digest, encoding)
		}

