func TestStore_Fetch_ExternalLocalUpdate(t *testing.T) {
	dir, repo := testRepository(t,
		layer("default", `{"namespace":"default","flags":[{"key":"first","name":"First"}]}`, MediaTypeFliptNamespace),
	)
	store, err := NewStore(&config.OCI{
		BundleDirectory: dir,
		Repository:      fmt.Sprintf("flipt://local/%s:latest", repo),
	})
	require.NoError(t, err)

	ctx := context.Background()
	first, err := store.Fetch(ctx)
	require.NoError(t, err)
	for _, file := range first.Files {
		require.NoError(t, file.Close())
	}

	// Another store instance publishes a new manifest to the same OCI layout.
	publisher, err := oci.New(path.Join(dir, repo))
	require.NoError(t, err)
	publisher.AutoSaveIndex = true
	updatedLayer := layer("default", `{"namespace":"default","flags":[{"key":"second","name":"Second"}]}`, MediaTypeFliptNamespace)(t, publisher)
	desc, err := oras.PackManifest(ctx, publisher, oras.PackManifestVersion1_1_RC4, MediaTypeFliptFeatures, oras.PackManifestOptions{
		ManifestAnnotations: map[string]string{},
		Layers:              []v1.Descriptor{updatedLayer},
	})
	require.NoError(t, err)
	require.NoError(t, publisher.Tag(ctx, desc, "latest"))

	second, err := store.Fetch(ctx, IfNoMatch(first.Digest))
	require.NoError(t, err)
	require.False(t, second.Matched)
	require.NotEqual(t, first.Digest, second.Digest)
	snapshot, err := storagefs.SnapshotFromFiles(second.Files...)
	require.NoError(t, err)
	flag, err := snapshot.GetFlag(ctx, "default", "second")
	require.NoError(t, err)
	assert.Equal(t, "Second", flag.Name)

	matched, err := store.Fetch(ctx, IfNoMatch(second.Digest))
	require.NoError(t, err)
	assert.True(t, matched.Matched)
	assert.Empty(t, matched.Files)
}

