	second, err := store.Fetch(ctx, IfNoMatch(first.Digest))
	require.NoError(t, err)
	require.False(t, second.Matched)
	require.NotEqual(t, first.Digest, second.Digest)
	snapshot, err := storagefs.SnapshotFromFiles(second.Files...)
	require.NoError(t, err)
	flag, err := snapshot.GetFlag(ctx, "default", "second")
	require.NoError(t, err)
	assert.Equal(t, "Second", flag.Name)

	matched, err := store.Fetch(ctx, IfNoMatch(second.Digest))
	require.NoError(t, err)
	assert.True(t, matched.Matched)
	assert.Empty(t, matched.Files)
}

